import type { Abi } from "viem";

/**
 * Lazy canonical-ABI loader over `abi/*.json` (generated by solc — AGENTS.md:
 * never hand-transcribed). Same glob pattern STUDIO uses; shared so the
 * identity panels encode with the exact same artifacts.
 */

const ABI_FILES = import.meta.glob("../../../abi/*.json") as Record<
  string,
  () => Promise<{ default: Abi }>
>;

const cache = new Map<string, Promise<Abi>>();

export function loadAbi(abiFile: string): Promise<Abi> {
  const hit = cache.get(abiFile);
  if (hit) return hit;
  const loader = ABI_FILES[`../../../abi/${abiFile}`];
  if (!loader) return Promise.reject(new Error(`ABI not found: ${abiFile}`));
  const p = loader().then((m) => m.default);
  cache.set(abiFile, p);
  return p;
}
